/*
 * ENCBound restart - native tests for the step 5 SDK sealing adapters
 * (wrappers/sdk_adapters.c).
 *
 * Built twice (MAC27 and RADIX_ONLY). The fake platform maps real memory at
 * enclave_base, so decoded raw addresses are dereferenceable. The SDK sealing
 * API is replaced by a recording stub; if an adapter passed a tagged
 * capability instead of a decoded address, the stub's memcpy would fault.
 *
 * The four sgx-wallet OCALL adapters are no longer handwritten and are no
 * longer tested here; they are generated by tools/encbound_edl.py and covered
 * by tests/generated_ocalls_test.c.
 */

#include <setjmp.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <sgx_error.h>
#include <sgx_tseal.h>

#include "encbound_common.h"
#include "encbound_runtime.h"

#include "encbound_adapters.h"

#include "fake_platform.h"
#include "test_harness.h"

#ifndef UINT32_MAX
#define UINT32_MAX 0xffffffffU
#endif

#define KEY0 0x0706050403020100ull
#define KEY1 0x0f0e0d0c0b0a0908ull

#define TEST_TEXT 32u

#define EXPECT_ABORT(code, stmt)                                               \
    do {                                                                       \
        fake_abort_active = 1;                                                 \
        if (setjmp(fake_abort_env) == 0) {                                     \
            stmt;                                                              \
            g_checks++;                                                        \
            g_failures++;                                                      \
            printf("FAIL %s:%d: expected abort %d\n", __FILE__, __LINE__,      \
                   (code));                                                    \
        } else {                                                               \
            CHECK_EQ(fake_abort_code, (code));                                 \
        }                                                                      \
        fake_abort_active = 0;                                                 \
    } while (0)

/* ---- SDK stand-ins ------------------------------------------------------ */

static unsigned char g_plain[TEST_TEXT];
static int g_seal_calls;

uint32_t sgx_calc_sealed_data_size(uint32_t add_mac_txt_size,
                                   uint32_t txt_encrypt_size)
{
    if (add_mac_txt_size > UINT32_MAX - txt_encrypt_size) {
        return UINT32_MAX;
    }
    if (add_mac_txt_size + txt_encrypt_size >
        UINT32_MAX - (uint32_t)sizeof(sgx_sealed_data_t)) {
        return UINT32_MAX;
    }
    return (uint32_t)sizeof(sgx_sealed_data_t) + add_mac_txt_size +
           txt_encrypt_size;
}

uint32_t sgx_get_add_mac_txt_len(const sgx_sealed_data_t *p_sealed_data)
{
    uint32_t data_size;

    if (p_sealed_data == NULL) {
        return UINT32_MAX;
    }
    data_size =
        p_sealed_data->aes_data.payload_size - p_sealed_data->plain_text_offset;
    if (data_size > p_sealed_data->aes_data.payload_size) {
        return UINT32_MAX;
    }
    return data_size;
}

uint32_t sgx_get_encrypt_txt_len(const sgx_sealed_data_t *p_sealed_data)
{
    return p_sealed_data == NULL ? UINT32_MAX
                                 : p_sealed_data->plain_text_offset;
}

sgx_status_t sgx_seal_data(uint32_t additional_MACtext_length,
                           const uint8_t *p_additional_MACtext,
                           uint32_t text2encrypt_length,
                           const uint8_t *p_text2encrypt,
                           uint32_t sealed_data_size,
                           sgx_sealed_data_t *p_sealed_data)
{
    if (text2encrypt_length == 0 || p_text2encrypt == NULL ||
        p_sealed_data == NULL ||
        sealed_data_size !=
            sgx_calc_sealed_data_size(additional_MACtext_length,
                                      text2encrypt_length)) {
        return SGX_ERROR_INVALID_PARAMETER;
    }
    g_seal_calls++;
    memset(p_sealed_data, 0, sizeof(sgx_sealed_data_t));
    p_sealed_data->plain_text_offset = text2encrypt_length;
    p_sealed_data->aes_data.payload_size =
        additional_MACtext_length + text2encrypt_length;
    if (additional_MACtext_length > 0) {
        memcpy(p_sealed_data->aes_data.payload, p_additional_MACtext,
               additional_MACtext_length);
    }
    memcpy(p_sealed_data->aes_data.payload + additional_MACtext_length,
           p_text2encrypt, text2encrypt_length);
    return SGX_SUCCESS;
}

sgx_status_t sgx_unseal_data(const sgx_sealed_data_t *p_sealed_data,
                             uint8_t *p_additional_MACtext,
                             uint32_t *p_additional_MACtext_length,
                             uint8_t *p_decrypted_text,
                             uint32_t *p_decrypted_text_length)
{
    uint32_t enc_len;
    uint32_t add_len;

    (void)p_additional_MACtext;
    if (p_sealed_data == NULL || p_decrypted_text == NULL ||
        p_decrypted_text_length == NULL) {
        return SGX_ERROR_INVALID_PARAMETER;
    }
    enc_len = sgx_get_encrypt_txt_len(p_sealed_data);
    add_len = sgx_get_add_mac_txt_len(p_sealed_data);
    if (enc_len == UINT32_MAX || add_len == UINT32_MAX ||
        *p_decrypted_text_length < enc_len) {
        return SGX_ERROR_INVALID_PARAMETER;
    }
    memcpy(p_decrypted_text,
           p_sealed_data->aes_data.payload + add_len, enc_len);
    *p_decrypted_text_length = enc_len;
    return SGX_SUCCESS;
}

/* ---- helpers ------------------------------------------------------------ */

static unsigned char *raw_of(void *cap, size_t n, int kind)
{
    return (unsigned char *)encbound_require((uintptr_t)cap, n, kind);
}

static const char *sealed_payload(void *sealed)
{
    return (const char *)((sgx_sealed_data_t *)raw_of(
                              sealed, sizeof(sgx_sealed_data_t),
                              ENCBOUND_ACCESS_READ))
        ->aes_data.payload;
}

/* ---- tests -------------------------------------------------------------- */

static void test_seal_unseal(void)
{
    uint32_t sealed_size =
        (uint32_t)(sizeof(sgx_sealed_data_t) + TEST_TEXT);
    void *wallet = encbound_malloc(TEST_TEXT);
    void *sealed = encbound_malloc(sealed_size);
    void *plain = encbound_malloc(TEST_TEXT);
    unsigned char *w;
    uint32_t capacity = TEST_TEXT;
    unsigned int i;

    CHECK(wallet != NULL && sealed != NULL && plain != NULL);
    w = raw_of(wallet, TEST_TEXT, ENCBOUND_ACCESS_WRITE);
    for (i = 0; i < TEST_TEXT; ++i) {
        w[i] = (unsigned char)(0xa0u + i);
        g_plain[i] = (unsigned char)(0xa0u + i);
    }

    g_seal_calls = 0;
    CHECK_EQ(encbound_sgx_seal_data(0, NULL, TEST_TEXT, wallet, sealed_size,
                                    (sgx_sealed_data_t *)sealed),
             SGX_SUCCESS);
    CHECK_EQ(g_seal_calls, 1);
    CHECK(memcmp(sealed_payload(sealed), g_plain, TEST_TEXT) == 0);

    CHECK_EQ(encbound_sgx_unseal_data((const sgx_sealed_data_t *)sealed, NULL,
                                      NULL, (uint8_t *)plain, &capacity),
             SGX_SUCCESS);
    CHECK_EQ(capacity, TEST_TEXT);
    CHECK(memcmp(raw_of(plain, TEST_TEXT, ENCBOUND_ACCESS_READ), g_plain,
                 TEST_TEXT) == 0);

    /* Zero-length encrypt input is rejected, not decoded. */
    CHECK_EQ(encbound_sgx_seal_data(0, NULL, 0, wallet, sealed_size,
                                    (sgx_sealed_data_t *)sealed),
             SGX_ERROR_INVALID_PARAMETER);
    /* Sealed output overruns its slot: protection failure. */
    EXPECT_ABORT(ENCBOUND_ERR_RANGE,
                 (void)encbound_sgx_seal_data(
                     0, NULL, TEST_TEXT, wallet, sealed_size + 4096,
                     (sgx_sealed_data_t *)sealed));
    /* Plaintext source is not fully authorized: protection failure. */
    EXPECT_ABORT(ENCBOUND_ERR_RANGE,
                 (void)encbound_sgx_seal_data(
                     0, NULL, TEST_TEXT,
                     (const uint8_t *)wallet + TEST_TEXT - 4,
                     sealed_size, (sgx_sealed_data_t *)sealed));
}

static void test_unseal_bounds(void)
{
    uint32_t sealed_size =
        (uint32_t)(sizeof(sgx_sealed_data_t) + TEST_TEXT);
    void *wallet = encbound_malloc(TEST_TEXT);
    void *sealed = encbound_malloc(sealed_size);
    void *plain = encbound_malloc(TEST_TEXT);
    void *plain64 = encbound_malloc(64);
    uint32_t capacity;
    sgx_sealed_data_t *hdr;

    CHECK(wallet != NULL && sealed != NULL && plain != NULL && plain64 != NULL);
    encbound_memset(wallet, 0x5a, TEST_TEXT);
    CHECK_EQ(encbound_sgx_seal_data(0, NULL, TEST_TEXT, wallet, sealed_size,
                                    (sgx_sealed_data_t *)sealed),
             SGX_SUCCESS);

    /* A caller buffer smaller than the sealed plaintext is an ordinary error,
       not an abort: no memory is written. */
    capacity = TEST_TEXT / 2;
    CHECK_EQ(encbound_sgx_unseal_data((const sgx_sealed_data_t *)sealed, NULL,
                                      NULL, (uint8_t *)plain, &capacity),
             SGX_ERROR_INVALID_PARAMETER);

    /* The blob header is host-controlled. A claimed payload larger than the
       validated object extent must be refused before the SDK reads it. */
    hdr = (sgx_sealed_data_t *)raw_of(sealed, sizeof(sgx_sealed_data_t),
                                      ENCBOUND_ACCESS_WRITE);
    hdr->aes_data.payload_size = 0xfffffff0u;
    capacity = TEST_TEXT;
    CHECK_EQ(encbound_sgx_unseal_data((const sgx_sealed_data_t *)sealed, NULL,
                                      NULL, (uint8_t *)plain, &capacity),
             SGX_ERROR_MAC_MISMATCH);
    encbound_sgx_seal_data(0, NULL, TEST_TEXT, wallet, sealed_size,
                           (sgx_sealed_data_t *)sealed);

    /* The output range must fit its slot even though the caller claims room. */
    capacity = TEST_TEXT;
    EXPECT_ABORT(ENCBOUND_ERR_RANGE,
                 (void)encbound_sgx_unseal_data(
                     (const sgx_sealed_data_t *)sealed, NULL, NULL,
                     (uint8_t *)plain64 + 48, &capacity));

    /* Wrong region and stripped capabilities are rejected before any read. */
    EXPECT_ABORT(ENCBOUND_ERR_POLICY,
                 (void)encbound_sgx_unseal_data(
                     (const sgx_sealed_data_t *)(((uintptr_t)sealed &
                                                  ~ENCBOUND_OFFSET_MASK) |
                                                 0x300000ull),
                     NULL, NULL, (uint8_t *)plain, &capacity));
    EXPECT_ABORT(ENCBOUND_ERR_POLICY,
                 (void)encbound_sgx_unseal_data(
                     (const sgx_sealed_data_t *)((uintptr_t)sealed &
                                                 ENCBOUND_OFFSET_MASK),
                     NULL, NULL, (uint8_t *)plain, &capacity));

#ifdef ENCBOUND_MAC27
    {
        uintptr_t forged = (uintptr_t)sealed + (1ull << ENCBOUND_RADIX_SHIFT);
        EXPECT_ABORT(ENCBOUND_ERR_TAG,
                     (void)encbound_sgx_unseal_data(
                         (const sgx_sealed_data_t *)forged, NULL, NULL,
                         (uint8_t *)plain, &capacity));
    }
#endif
}

int main(void)
{
    CHECK_EQ(encbound_runtime_init_with_key(KEY0, KEY1), ENCBOUND_OK);
    CHECK(encbound_runtime_ready());

    test_seal_unseal();
    test_unseal_bounds();

    return TEST_SUMMARY("sdk_adapters_test");
}
